    if connection then
        return
    end
    connection = RunService.Heartbeat:Connect(function()
        local now = tick()
        if not currentTask or not currentTask.isEnabled() or now > sliceEnd then
            local next_ = pickNextEnabled()
            if next_ ~= currentTask then
                currentTask = next_
                log(S(327) .. (currentTask and currentTask.name or S(353)))
            end
            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            local ok, err = pcall(currentTask.step)
            if not ok then
                log(S(5) .. currentTask.name .. S(218) .. tostring(err))
            end
        end
    end)
end
function scheduler.Stop()
    if connection then
        connection:Disconnect()
        connection = nil
    end
    currentTask = nil
end
return scheduler
end
